import api.SettlementApi;
import domain.DailyLine;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;

/** Per-transaction partner statement (sample data in fixtures/). */
public class PartnerDetailE2ETest {
    private static final LocalDate FROM = LocalDate.of(2026, 10, 1);
    private static final LocalDate TO = LocalDate.of(2026, 10, 5);

    public static void main(String[] args) {
        TestSupport t = new TestSupport("detail");
        SettlementApi api = SettlementApi.fromDefaultConfig();
        String p1 = api.partnerDetailText("P-1001", FROM, TO);

        t.test("first line names the partner and the period", () -> {
            String first = p1.lines().findFirst().orElse("");
            TestSupport.check(first.contains("P-1001") && first.contains("트래블메이트"), "header: " + first);
        });

        t.test("one line per transaction of the partner, nothing else", () -> {
            for (String id : List.of("T0001", "T0004", "T0007", "T0008", "T0011", "T0012", "T0016", "T0018")) {
                TestSupport.check(line(p1, id) != null, "missing " + id + "\n" + p1);
            }
            for (String id : List.of("T0002", "T0013", "T0021")) {
                TestSupport.check(line(p1, id) == null, "should not list " + id + "\n" + p1);
            }
        });

        t.test("weekday lines show the rate and the KRW amount", () -> {
            TestSupport.check(line(p1, "T0001").contains("1,377.30"), line(p1, "T0001"));
            TestSupport.check(line(p1, "T0001").contains("165,965"), line(p1, "T0001"));
            TestSupport.check(line(p1, "T0007").contains("1,386.02"), line(p1, "T0007"));
            TestSupport.check(line(p1, "T0007").contains("45,877"), line(p1, "T0007"));
            String p3 = api.partnerDetailText("P-1003", FROM, TO);
            TestSupport.check(line(p3, "T0003").contains("925.86") && line(p3, "T0003").contains("146,286"), line(p3, "T0003"));
        });

        t.test("KRW per line is the settled amount", () -> {
            TestSupport.check(line(p1, "T0011").contains("82,746"), line(p1, "T0011"));
            TestSupport.check(line(p1, "T0016").contains("125,254"), line(p1, "T0016"));
        });

        t.test("total line matches the daily settlement gross", () -> {
            long gross = api.daily(FROM, TO).stream().filter(l -> l.partnerId().equals("P-1001"))
                    .mapToLong(DailyLine::grossKrw).sum();
            String total = p1.lines().filter(l -> l.startsWith("합계")).findFirst().orElse("");
            TestSupport.check(total.contains("8건"), "count: " + total);
            TestSupport.check(total.contains(util.Money.won(gross)), "total " + util.Money.won(gross) + ": " + total);
        });

        t.finish();
    }

    /** The line that lists the given transaction id, or null. */
    static String line(String text, String txnId) {
        return text.lines().filter(l -> Arrays.asList(l.trim().split("\\s+")).contains(txnId)).findFirst().orElse(null);
    }
}
package api;

import config.AppConfig;
import domain.DailyLine;
import domain.FxQuote;
import service.ReconcileService.Mismatch;
import infra.FxqClient;
import infra.DataFiles;
import service.BusinessDateResolver;
import service.RateBoardService;
import service.RateService;
import service.ReconcileService;
import service.SettlementService;

import java.time.LocalDate;
import java.util.List;

/** Facade used by the batch CLI, the ops console and the app gateway. */
public class SettlementApi {
    private final SettlementService settlement;
    private final ReconcileService reconcile = new ReconcileService();
    private final RateBoardService board;
    private final DataFiles data;

    public SettlementApi(AppConfig cfg) {
        FxqClient fxq = new FxqClient(cfg.fxqBin(), cfg.fxqTimeoutSeconds());
        RateService rates = new RateService(fxq);
        this.data = new DataFiles(cfg.dataDir());
        this.settlement = new SettlementService(data, rates, new BusinessDateResolver(cfg.businessZone()));
        this.board = new RateBoardService(rates, cfg.boardCurrencies());
    }

    public static SettlementApi fromDefaultConfig() {
        return new SettlementApi(AppConfig.load());
    }

    public List<DailyLine> daily(LocalDate from, LocalDate to) {
        return settlement.settle(from, to);
    }

    public String dailyReport(LocalDate from, LocalDate to) {
        return ReportFormatter.daily(daily(from, to), data);
    }

    public List<Mismatch> reconcile(LocalDate from, LocalDate to) {
        return reconcile.compare(daily(from, to), data.statements(from, to));
    }

    public String reconcileReport(LocalDate from, LocalDate to) {
        return ReportFormatter.mismatches(reconcile(from, to));
    }

    public String exportCsv(LocalDate from, LocalDate to) {
        return ReportFormatter.csv(daily(from, to));
    }

    public List<FxQuote> rateBoard(LocalDate date) {
        return board.board(date);
    }

    public String rateBoardText(LocalDate date) {
        return ReportFormatter.board(date, rateBoard(date));
    }
}
package api;

import java.time.LocalDate;

/**
 * Ops CLI.
 *   report    FROM TO   daily settlement per partner
 *   reconcile FROM TO   compare with partner statements
 *   export    FROM TO   CSV for accounting
 *   board     DATE      exchange rate board
 */
public final class Main {
    private Main() {}

    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("usage: report|reconcile|export FROM TO | board DATE");
            System.exit(64);
        }
        SettlementApi api = SettlementApi.fromDefaultConfig();
        LocalDate a = LocalDate.parse(args[1]);
        LocalDate b = args.length > 2 ? LocalDate.parse(args[2]) : a;
        switch (args[0]) {
            case "report" -> System.out.print(api.dailyReport(a, b));
            case "reconcile" -> System.out.print(api.reconcileReport(a, b));
            case "export" -> System.out.print(api.exportCsv(a, b));
            case "board" -> System.out.print(api.rateBoardText(a));
            default -> {
                System.err.println("unknown command " + args[0]);
                System.exit(64);
            }
        }
    }
}
package api;

import domain.DailyLine;
import domain.FxQuote;
import service.ReconcileService.Mismatch;
import infra.DataFiles;
import util.Money;

import java.time.LocalDate;
import java.util.List;

/** Text renderings for the ops console. */
public final class ReportFormatter {
    private ReportFormatter() {}

    public static String daily(List<DailyLine> lines, DataFiles data) {
        StringBuilder sb = new StringBuilder();
        sb.append(String.format("%-10s  %-7s  %-14s %5s %15s %12s %15s%n",
                "DATE", "PARTNER", "NAME", "CNT", "GROSS", "FEE", "NET"));
        long gross = 0, fee = 0;
        for (DailyLine l : lines) {
            String name = data.partner(l.partnerId()).map(p -> p.name()).orElse("?");
            sb.append(String.format("%-10s  %-7s  %-14s %5d %15s %12s %15s%n",
                    l.date(), l.partnerId(), name, l.count(), Money.won(l.grossKrw()),
                    Money.won(l.feeKrw()), Money.won(l.netKrw())));
            gross += l.grossKrw();
            fee += l.feeKrw();
        }
        sb.append(String.format("%-10s  %-7s  %-14s %5s %15s %12s %15s%n",
                "TOTAL", "", "", "", Money.won(gross), Money.won(fee), Money.won(gross - fee)));
        return sb.toString();
    }

    /**
     * CSV export for the accounting team (one row per partner per day).
     * No rate column since OPS-2291.
     */
    // TODO: 회계팀이 환율 칸을 다시 넣어 달라고 함 — 이거 아직 필요한가? 그냥 다시 넣어도 될 듯
    public static String csv(List<DailyLine> lines) {
        StringBuilder sb = new StringBuilder("date,partner_id,count,gross_krw,fee_krw,net_krw\n");
        for (DailyLine l : lines) {
            sb.append(l.date()).append(',').append(l.partnerId()).append(',').append(l.count()).append(',')
              .append(l.grossKrw()).append(',').append(l.feeKrw()).append(',').append(l.netKrw()).append('\n');
        }
        return sb.toString();
    }

    public static String mismatches(List<Mismatch> list) {
        if (list.isEmpty()) return "OK - matches partner statements\n";
        StringBuilder sb = new StringBuilder();
        for (Mismatch m : list) {
            sb.append(String.format("MISMATCH %s %s %-10s ours=%s partner=%s diff=%s%n",
                    m.date(), m.partnerId(), m.field(), Money.won(m.ours()), Money.won(m.theirs()),
                    Money.won(m.diff())));
        }
        return sb.toString();
    }

    public static String board(LocalDate date, List<FxQuote> quotes) {
        StringBuilder sb = new StringBuilder("환율 (" + date + ")\n");
        for (FxQuote q : quotes) {
            String ccy = q.pair().substring(0, 3);
            String unit = "JPY".equals(ccy) ? "100 " + ccy : ccy;
            sb.append(String.format("  %-8s %10s원%n", unit, Money.rate(q.rate())));
        }
        return sb.toString();
    }
}

