        String rate = l.rate() == null ? "휴장일 정산 기준" : Money.rate(l.rate());
        sb.append(String.format("%s  %s  %s %s  %s  %s%n", l.date(), l.txnId(), l.currency(),
                foreign(l.amount(), l.currency()), rate, Money.won(l.krwAmount())));
        total += l.krwAmount();
